/**
 * The Peptide Library's data layer.
 *
 * Structure is Superpower's peptide library (superpower.com/guides/peptides),
 * adopted on 2026-11-06: eight body-system categories, four regulatory
 * status labels, a five-step evidence scale, and one guide page per compound
 * with a fixed anatomy (key takeaway, byline, at a glance, sections, status
 * box, evidence box, related). Nothing here is invented; where this module
 * and that site disagree, the site is the reference.
 *
 * Guides are generated by `scripts/build-library-guides.mjs` into
 * `lib/data/guides/<slug>.json` and never hand-edited. The index of which
 * compounds exist, and in which category, is `lib/data/guide-index.json`.
 *
 * The app's catalog (`lib/library.ts`, 54 compounds) is a separate dataset:
 * it still powers the reconstitution calculators and the shop's compound
 * facts (vial sizes, routes). The two are joined by slug via `catalogSlug`.
 */

import guideIndex from "./data/guide-index.json";
import guideBundle from "./data/guides.json";
import guideSeed from "./data/guide-seed.json";
import { dashesToCommas } from "./library";

import { CATEGORIES, STATUSES, EVIDENCE, STATUS_ORDER, statusLabel, type CategorySlug, type CategoryMeta, type StatusKey, type Evidence } from "./guideVocab";
export { CATEGORIES, STATUSES, EVIDENCE, statusLabel };
export type { CategorySlug, CategoryMeta, StatusKey, Evidence };

/* ---- Guide shape --------------------------------------------------------- */

export type Block =
  | { type: "p"; text: string }
  | { type: "ul"; items: string[] }
  | { type: "timeline"; items: { date: string; text: string }[] }
  | { type: "table"; columns: string[]; rows: string[][]; note?: string };

export interface GuideSection {
  id: string;
  heading: string;
  blocks: Block[];
}

export interface Source {
  id: number;
  title: string;
  /** Journal, agency, or company. */
  publisher: string;
  year?: number | null;
  url?: string | null;
  doi?: string | null;
  pmid?: string | null;
  /** Set by the validator's live check. Unverified sources never render. */
  verified: boolean;
}

export interface Guide {
  slug: string;
  name: string;
  /** "Also called ..." line under the title. */
  alsoCalled?: string;
  class: string;
  category: CategorySlug;
  status: StatusKey;
  evidence: Evidence;
  /** The sentence in the Evidence strength box that explains the rating. */
  evidenceNote: string;
  keyTakeaway: string;
  /** 4-5 rows. The last is always "Evidence strength". */
  atGlance: { label: string; value: string }[];
  sections: GuideSection[];
  /** The grey Status box under "Is it FDA-approved?". */
  statusBox: { label: string; value: string }[];
  sources: Source[];
  /** One or two sentences on the kinds of sources used; the page appends the disclaimer. */
  sourcesNote?: string;
  /** Slugs of the compound's variants or close relatives that have guides. */
  alsoInLibrary?: string[];
  /** Slug in the app catalog (`lib/library.ts`), when the compound is there. */
  catalogSlug?: string;
  published: string;
  updated: string;
  /** Short description for <meta>, cards, and the index. */
  summary: string;
}

/* ---- Index --------------------------------------------------------------- */

export interface IndexRow {
  slug: string;
  name: string;
  category: CategorySlug;
  status: StatusKey;
  catalogSlug?: string;
  /** True once a guide JSON exists for the slug. */
  hasGuide: boolean;
}

const INDEX = (guideIndex as IndexRow[]).slice().sort((a, b) =>
  a.name.localeCompare(b.name, "en", { sensitivity: "base" })
);

export const GUIDE_INDEX: readonly IndexRow[] = INDEX;

export function categoryBySlug(slug: string): CategoryMeta | undefined {
  return CATEGORIES.find((c) => c.slug === slug);
}

export function rowsInCategory(slug: CategorySlug): IndexRow[] {
  return INDEX.filter((r) => r.category === slug);
}

export function categoryCount(slug: CategorySlug): number {
  return rowsInCategory(slug).length;
}

export function indexRow(slug: string): IndexRow | undefined {
  return INDEX.find((r) => r.slug === slug);
}

export function guideHref(slug: string): string {
  return `/library/${slug}`;
}

export function categoryHref(slug: CategorySlug): string {
  return `/library/${slug}`;
}

/** The library's section tabs: all, then the eight body systems with counts. */
export function libraryTabs(): { key: string; label: string; href: string; count: number }[] {
  return [
    { key: "all", label: "All", href: "/library", count: INDEX.length },
    ...CATEGORIES.map((c) => ({ key: c.slug, label: c.short, href: categoryHref(c.slug), count: rowsInCategory(c.slug).length })),
  ];
}

/** Reference facts for a compound whose full guide is not written yet. */
export interface Brief {
  slug: string;
  name: string;
  alsoCalled?: string;
  className?: string;
  evidence?: string;
  category: CategorySlug;
  status: StatusKey;
}

export function briefBySlug(slug: string): Brief | undefined {
  const row = indexRow(slug);
  if (!row) return undefined;
  const s = (guideSeed as { slug: string; alsoCalled?: string; referenceClass?: string; referenceEvidence?: string }[]).find((x) => x.slug === slug);
  return {
    slug,
    name: row.name,
    alsoCalled: s?.alsoCalled ? dashesToCommas(s.alsoCalled) : undefined,
    className: s?.referenceClass ? dashesToCommas(s.referenceClass) : undefined,
    evidence: s?.referenceEvidence,
    category: row.category,
    status: row.status,
  };
}

/* ---- Guides -------------------------------------------------------------- */

// The generator writes one JSON per compound under `data/guides/` (readable
// diffs), and `scripts/bundle-guides.mjs` folds them into `data/guides.json`
// so the module is a static import: no runtime `fs`, nothing for Vercel's
// file tracing to miss, and the sitemap can read it synchronously. The
// bundle is cleaned ONCE at module load, the same rule library.ts applies to
// the catalog, so meta descriptions, OG images, JSON-LD and llms.txt all
// read the normalised text.
let guideCache: Map<string, Guide> | null = null;

function loadAll(): Map<string, Guide> {
  if (guideCache) return guideCache;
  guideCache = new Map();
  for (const raw of guideBundle as Guide[]) guideCache.set(raw.slug, cleanGuide(raw));
  return guideCache;
}

/** Every guide, sorted by name. */
export function allGuides(): Guide[] {
  return [...loadAll().values()].sort((a, b) =>
    a.name.localeCompare(b.name, "en", { sensitivity: "base" })
  );
}

export function guideBySlug(slug: string): Guide | undefined {
  return loadAll().get(slug);
}

/** Guides in the same category, excluding the compound itself. */
export function relatedGuides(guide: Guide, limit = 6): Guide[] {
  const peers = allGuides().filter(
    (g) => g.category === guide.category && g.slug !== guide.slug
  );
  // Approved drugs first, then by name: the same ordering the category
  // sections use, so "More for X" reads as a slice of the category.
  peers.sort((a, b) => STATUS_ORDER.indexOf(a.status) - STATUS_ORDER.indexOf(b.status));
  return peers.slice(0, limit);
}

/** The catalog's dose-cards and vial facts are keyed by catalog slug. */
export function catalogSlugFor(guide: Guide): string | undefined {
  return guide.catalogSlug ?? indexRow(guide.slug)?.catalogSlug;
}

/* ---- Normalisation --------------------------------------------------------- */

// The generator is told not to write dashes, but the copy rule is enforced at
// load time anyway, the same way the catalog is cleaned in library.ts: one
// pass here covers meta descriptions, OG images, JSON-LD and llms.txt.
function cleanText(s: string): string {
  return dashesToCommas(s);
}

function cleanBlock(b: Block): Block {
  switch (b.type) {
    case "p":
      return { type: "p", text: cleanText(b.text) };
    case "ul":
      return { type: "ul", items: b.items.map(cleanText) };
    case "timeline":
      return {
        type: "timeline",
        items: b.items.map((i) => ({ date: cleanText(i.date), text: cleanText(i.text) })),
      };
    case "table":
      return {
        type: "table",
        columns: b.columns.map(cleanText),
        rows: b.rows.map((r) => r.map(cleanText)),
        note: b.note ? cleanText(b.note) : undefined,
      };
  }
}

function cleanGuide(g: Guide): Guide {
  return {
    ...g,
    alsoCalled: g.alsoCalled ? cleanText(g.alsoCalled) : undefined,
    class: cleanText(g.class),
    evidenceNote: cleanText(g.evidenceNote),
    keyTakeaway: cleanText(g.keyTakeaway),
    summary: cleanText(g.summary),
    atGlance: g.atGlance.map((r) => ({ label: cleanText(r.label), value: cleanText(r.value) })),
    statusBox: g.statusBox.map((r) => ({ label: cleanText(r.label), value: cleanText(r.value) })),
    sections: g.sections.map((s) => ({ ...s, heading: cleanText(s.heading), blocks: s.blocks.map(cleanBlock) })),
    sources: g.sources.map((s) => ({ ...s, title: cleanText(s.title), publisher: cleanText(s.publisher) })),
    sourcesNote: g.sourcesNote ? cleanText(g.sourcesNote) : undefined,
  };
}

/* ---- Citations ------------------------------------------------------------- */

/**
 * Inline markers are written as `[n]` in guide text. Only verified sources
 * render; a marker pointing at a dropped source is removed from the text so
 * the page never shows a number with nothing behind it.
 */
export function renderableSources(guide: Guide): Source[] {
  return guide.sources.filter((s) => s.verified);
}

export function stripDeadMarkers(text: string, guide: Guide): string {
  const live = new Set(renderableSources(guide).map((s) => s.id));
  return text.replace(/\s?\[(\d+)\]/g, (m, n) => (live.has(Number(n)) ? m : ""));
}

export function sourceMeta(s: Source): string {
  const head = s.year ? `${s.publisher}, ${s.year}` : s.publisher;
  if (s.doi) return `${head} · DOI ${s.doi}`;
  if (s.pmid) return `${head} · PMID ${s.pmid}`;
  if (s.url) {
    try {
      return `${head} · ${new URL(s.url).hostname.replace(/^www\./, "")}`;
    } catch {
      return head;
    }
  }
  return head;
}

export function sourceHref(s: Source): string | undefined {
  return s.url ?? (s.doi ? `https://doi.org/${s.doi}` : s.pmid ? `https://pubmed.ncbi.nlm.nih.gov/${s.pmid}/` : undefined);
}

/** Index rows the client hub needs, nothing else. */
export interface HubRow {
  slug: string;
  name: string;
  category: CategorySlug;
  status: StatusKey;
  hasGuide: boolean;
  className?: string;
}

export function hubRows(): HubRow[] {
  const guides = new Map(allGuides().map((g) => [g.slug, g]));
  return INDEX.map((r) => ({ slug: r.slug, name: guides.get(r.slug)?.name ?? r.name, category: r.category, status: guides.get(r.slug)?.status ?? r.status, hasGuide: r.hasGuide, className: guides.get(r.slug)?.class }))
    .sort((a, b) => STATUS_ORDER.indexOf(a.status) - STATUS_ORDER.indexOf(b.status) || a.name.localeCompare(b.name));
}

/* ---- Reading time -------------------------------------------------------------- */

export function guideWordCount(guide: Guide): number {
  const parts: string[] = [guide.keyTakeaway, guide.evidenceNote];
  for (const r of guide.atGlance) parts.push(r.value);
  for (const s of guide.sections) {
    for (const b of s.blocks) {
      if (b.type === "p") parts.push(b.text);
      else if (b.type === "ul") parts.push(...b.items);
      else if (b.type === "timeline") parts.push(...b.items.map((i) => i.text));
      else parts.push(...b.rows.flat());
    }
  }
  return parts.join(" ").split(/\s+/).filter(Boolean).length;
}

export function guideReadMinutes(guide: Guide): number {
  return Math.max(1, Math.round(guideWordCount(guide) / 230));
}

/* ---- Search ------------------------------------------------------------------- */

/** The shape `LibrarySearch` filters: name first, then the blurb. */
export interface GuideSearchRow {
  slug: string;
  name: string;
  /** "Also called" names, so a search for "LY3437943" finds retatrutide. */
  blurb: string;
  /** Category label, shown beside the hit. */
  category: string;
  status: string;
  href: string;
}

export function guideSearchRows(): GuideSearchRow[] {
  const guides = new Map(allGuides().map((g) => [g.slug, g]));
  return INDEX.filter((r) => r.hasGuide).map((r) => {
    const g = guides.get(r.slug);
    return {
      slug: r.slug,
      name: r.name,
      blurb: g?.alsoCalled ?? g?.class ?? "",
      category: categoryBySlug(r.category)?.label ?? r.category,
      status: statusLabel(r.status),
      href: guideHref(r.slug),
    };
  });
}

export function formatGuideDate(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(+d)) return iso;
  return d.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
}
